export function sweepRetiredSegments(queue: RetiredSegment[], minActiveEpoch: bigint): number {
  let reclaimed = 0;
  while (queue.length > 0 && queue[0].retireEpoch < minActiveEpoch) {
    const seg = queue.shift()!;
    seg.unmapAndClose(); // safe: zero readers can observe <= retireEpoch
    reclaimed += 1;
  }
  return reclaimed;
}

