export async function sealAndSwapSegment(
  ctx: CompactionContext,
  nextSeg: MappedSegment,
  obsolete: MappedSegment[],
): Promise<ManifestRecord> {
  nextSeg.writeTrailerAndSeal();
  await nextSeg.syncToDisk({ fullSync: true });
  if (!nextSeg.verifyCrc32c()) {
    throw new WalIntegrityError('seal-crc-mismatch', nextSeg.id);
  }
  const current = await ctx.manifest.read();
  const updated = await ctx.manifest.compareAndSwap({
    expectGeneration: current.generation,
    add: [nextSeg.descriptor()],
    remove: obsolete.map((s) => s.id),
  });
  const retireEpoch = ctx.epochs.current();
  ctx.retirementQueue.push(...obsolete.map((seg) => ({ seg, retireEpoch })));
  return updated;
}

